// Opt-out ledger for marketing email, shared by every worker through STATE_DIR.
//
// Storage: an append-only NDJSON log at $STATE_DIR/email-optout-events.ndjson.
// Each record is one write, fsynced before the call resolves, so a restarted
// worker or another worker sees it. A record torn by a crash is skipped on read.
//
// Rules:
// - An unsubscribe blocks marketing mail. It never blocks transactional mail
//   (receipts, password resets).
// - A resubscribe lifts the block only when it is later than the latest unsubscribe.
// - Events are ordered by the provider's `at`, not by arrival. On a tie, unsubscribe wins.
// - Addresses match by canonical key: case-insensitive, display names and mailto:
//   stripped, +tags removed, and dots removed for gmail.com / googlemail.com.
// - Unknown kinds, invalid recipients and unreadable state fail closed.

import { mkdir, open, stat } from "node:fs/promises";
import { join } from "node:path";

const LOG_NAME = "email-optout-events.ndjson";
const KINDS = new Set(["marketing", "transactional"]);
const GMAIL_DOMAINS = new Set(["gmail.com", "googlemail.com"]);

// Per-process view of the log. The log only grows, so each sync parses only new bytes.
let view = freshView(null);
// Serializes syncs inside one process so two calls never apply the same bytes twice.
let chain = Promise.resolve();

export async function recordUnsubscribe(email, at) {
  await append("unsubscribe", email, at);
}

export async function recordResubscribe(email, at) {
  await append("resubscribe", email, at);
}

export async function mayEmail(message, now) {
  const nowMs = toMs(now, "now");
  const kind = message?.kind;
  if (!KINDS.has(kind)) return deny("invalid_kind");

  let key;
  try {
    key = canonicalKey(message.to);
  } catch {
    return deny("invalid_recipient");
  }

  // Receipts and password resets go out regardless of marketing opt-outs.
  if (kind === "transactional") return allow();

  let optedOut;
  try {
    await sync();
    optedOut = isOptedOut(key, nowMs);
  } catch {
    return deny("suppression_state_unavailable");
  }
  return optedOut ? deny("unsubscribed") : allow();
}

function allow() {
  return { allowed: true, reason: null };
}

function deny(reason) {
  return { allowed: false, reason };
}

function stateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error("STATE_DIR is not set");
  return dir;
}

function freshView(path) {
  return { path, offset: 0, keys: new Map() };
}

function serialize(task) {
  const run = chain.then(task);
  chain = run.catch(() => {});
  return run;
}

function toMs(value, name) {
  if (!(value instanceof Date) || Number.isNaN(value.getTime())) {
    throw new TypeError(`${name} must be a valid Date`);
  }
  return value.getTime();
}

// Maps any spelling of an address to one key per mailbox.
function canonicalKey(input) {
  if (typeof input !== "string") throw new TypeError("email must be a string");
  let s = input.normalize("NFKC").trim();
  if (/^mailto:/i.test(s)) s = s.replace(/^mailto:/i, "").replace(/\?.*$/, "");
  const angled = s.match(/<([^<>]*)>/);
  if (angled) s = angled[1].trim();

  const at = s.lastIndexOf("@");
  if (at < 1 || at === s.length - 1 || /\s/.test(s)) {
    throw new TypeError(`not an email address: ${input}`);
  }

  let local = s.slice(0, at).toLowerCase();
  let domain = s.slice(at + 1).toLowerCase().replace(/\.$/, "");
  local = local.split("+")[0] || local;
  if (GMAIL_DOMAINS.has(domain)) {
    local = local.replace(/\./g, "");
    domain = "gmail.com";
  }
  if (!local || !domain.includes(".")) {
    throw new TypeError(`not an email address: ${input}`);
  }
  return `${local}@${domain}`;
}

async function append(type, email, at) {
  const atMs = toMs(at, "at");
  canonicalKey(email); // reject bad addresses before they reach the log
  const dir = stateDir();
  await mkdir(dir, { recursive: true });
  const fh = await open(join(dir, LOG_NAME), "a");
  try {
    // The leading newline ends any record a crash left half-written.
    await fh.appendFile(`\n${JSON.stringify({ type, a: email, at: atMs })}\n`);
    await fh.sync();
  } finally {
    await fh.close();
  }
}

function sync() {
  return serialize(async () => {
    const path = join(stateDir(), LOG_NAME);
    if (view.path !== path) view = freshView(path);

    let size;
    try {
      size = (await stat(path)).size;
    } catch (err) {
      if (err.code !== "ENOENT") throw err;
      view = freshView(path);
      return;
    }
    if (size < view.offset) view = freshView(path); // file was replaced or truncated
    if (size === view.offset) return;

    const fh = await open(path, "r");
    try {
      const want = size - view.offset;
      const buf = Buffer.alloc(want);
      const { bytesRead } = await fh.read(buf, 0, want, view.offset);
      const end = buf.subarray(0, bytesRead).lastIndexOf(0x0a);
      if (end < 0) return; // no complete record yet
      for (const line of buf.subarray(0, end + 1).toString("utf8").split("\n")) {
        apply(line);
      }
      view.offset += end + 1;
    } finally {
      await fh.close();
    }
  });
}

function apply(line) {
  let ev;
  try {
    ev = JSON.parse(line);
  } catch {
    return; // blank line or a record torn by a crash
  }
  if (!ev || typeof ev.a !== "string" || !Number.isFinite(ev.at)) return;
  if (ev.type !== "unsubscribe" && ev.type !== "resubscribe") return;

  let key;
  try {
    key = canonicalKey(ev.a);
  } catch {
    return;
  }
  let entry = view.keys.get(key);
  if (!entry) {
    entry = { unsub: [], resub: [] };
    view.keys.set(key, entry);
  }
  (ev.type === "unsubscribe" ? entry.unsub : entry.resub).push(ev.at);
}

// State as of `nowMs`: the latest unsubscribe is not superseded by a resubscribe
// that happened at or before `nowMs`. Unsubscribes count even when dated after
// `nowMs` (provider clock skew), which errs toward blocking.
function isOptedOut(key, nowMs) {
  const entry = view.keys.get(key);
  if (!entry || entry.unsub.length === 0) return false;

  let lastUnsub = -Infinity;
  for (const t of entry.unsub) if (t > lastUnsub) lastUnsub = t;

  let lastResub = -Infinity;
  for (const t of entry.resub) if (t <= nowMs && t > lastResub) lastResub = t;

  return lastUnsub >= lastResub;
}

import { mkdtemp, appendFile, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawn } from "node:child_process";
import assert from "node:assert/strict";

const BOT = "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/courier-inv-g3-3/bot.mjs";
const fresh = (dir) => import(`${BOT}?v=${Math.random()}`);

// Child mode: N concurrent workers each record unsubscribes for distinct addresses.
if (process.argv[2] === "child") {
  const [, , , dir, tag, n] = process.argv;
  process.env.STATE_DIR = dir;
  const bot = await import(`${BOT}?child=${tag}`);
  for (let i = 0; i < Number(n); i++) {
    await bot.recordUnsubscribe(`w${tag}-${i}@example.com`, new Date(1000 + i));
  }
  process.exit(0);
}

const d = (ms) => new Date(ms);
const mk = (to, kind = "marketing") => ({ to, kind });
const dir = await mkdtemp(join(tmpdir(), "optout-"));
process.env.STATE_DIR = dir;
const bot = await fresh();
const NOW = d(10_000_000);

// 1. Unsubscribe blocks marketing, not transactional.
await bot.recordUnsubscribe("Bob <<EMAIL>>", d(1000));
assert.deepEqual(await bot.mayEmail(mk("<EMAIL>"), NOW), { allowed: false, reason: "unsubscribed" });
assert.deepEqual(await bot.mayEmail(mk("<EMAIL>", "transactional"), NOW), { allowed: true, reason: null });
assert.deepEqual(await bot.mayEmail(mk("other@example.com"), NOW), { allowed: true, reason: null });

// 2. Resubscribe later than unsubscribe lifts the block; earlier one does not.
await bot.recordResubscribe("<EMAIL>", d(2000));
assert.deepEqual(await bot.mayEmail(mk("<EMAIL>"), NOW), { allowed: true, reason: null });
await bot.recordResubscribe("carol@example.com", d(500));
await bot.recordUnsubscribe("carol@example.com", d(600));
assert.equal((await bot.mayEmail(mk("carol@example.com"), NOW)).reason, "unsubscribed");

// 3. Out of order: unsubscribe at 3000 arrives after resubscribe at 4000 wins only if later.
await bot.recordResubscribe("dan@example.com", d(4000));
await bot.recordUnsubscribe("dan@example.com", d(3000)); // late, older -> ignored
assert.equal((await bot.mayEmail(mk("dan@example.com"), NOW)).allowed, true);
await bot.recordUnsubscribe("dan@example.com", d(5000)); // newer -> blocks
assert.equal((await bot.mayEmail(mk("dan@example.com"), NOW)).reason, "unsubscribed");

// 4. Point-in-time: resubscribe dated after `now` is not yet effective.
await bot.recordUnsubscribe("eve@example.com", d(100));
await bot.recordResubscribe("eve@example.com", d(9_000_000));
assert.equal((await bot.mayEmail(mk("eve@example.com"), d(500))).reason, "unsubscribed");
assert.equal((await bot.mayEmail(mk("eve@example.com"), d(9_500_000))).allowed, true);

// 5. Tie: unsubscribe wins.
await bot.recordResubscribe("tie@example.com", d(777));
await bot.recordUnsubscribe("tie@example.com", d(777));
assert.equal((await bot.mayEmail(mk("tie@example.com"), NOW)).reason, "unsubscribed");

// 6. Header forms and mailto.
await bot.recordUnsubscribe('"Frank, Jr." <Frank@Example.com>', d(10));
assert.equal((await bot.mayEmail(mk("mailto:frank@example.com"), NOW)).reason, "unsubscribed");

// 7. Bad input.
assert.deepEqual(await bot.mayEmail(mk("x@example.com", "newsletter"), NOW), { allowed: false, reason: "invalid_kind" });
assert.deepEqual(await bot.mayEmail(mk("not-an-address"), NOW), { allowed: false, reason: "invalid_recipient" });
assert.deepEqual(await bot.mayEmail(undefined, NOW), { allowed: false, reason: "invalid_kind" });
await assert.rejects(bot.recordUnsubscribe("x@example.com", "2020-01-01"), TypeError);
await assert.rejects(bot.recordUnsubscribe("nope", d(1)), TypeError);

// 8. Torn write from a crash: garbage tail, then a valid record must still be read.
await appendFile(join(dir, "email-optout-events.ndjson"), '\n{"type":"unsub');
await bot.recordUnsubscribe("torn-next@example.com", d(42));
assert.equal((await bot.mayEmail(mk("torn-next@example.com"), NOW)).reason, "unsubscribed");

// 9. Restart: a fresh module instance (empty cache) reads the same state.
const restarted = await fresh();
assert.equal((await restarted.mayEmail(mk("<EMAIL>"), NOW)).allowed, true);
assert.equal((await restarted.mayEmail(mk("other2@example.com"), NOW)).allowed, true);
assert.equal((await restarted.mayEmail(mk("eve@example.com"), d(500))).reason, "unsubscribed");

// 10. Several workers writing at once.
const children = [];
for (const tag of ["A", "B", "C"]) {
  children.push(new Promise((res, rej) => {
    const p = spawn(process.execPath, [import.meta.filename, "child", dir, tag, "60"], { stdio: "inherit" });
    p.on("exit", (code) => (code === 0 ? res() : rej(new Error(`child ${tag} exit ${code}`))));
  }));
}
await Promise.all(children);
for (const tag of ["A", "B", "C"]) {
  for (let i = 0; i < 60; i++) {
    const r = await restarted.mayEmail(mk(`w${tag}-${i}@example.com`), NOW);
    assert.equal(r.reason, "unsubscribed", `missing w${tag}-${i}`);
  }
}

// 11. Missing STATE_DIR: marketing fails closed, transactional still goes.
const saved = process.env.STATE_DIR;
delete process.env.STATE_DIR;
assert.deepEqual(await restarted.mayEmail(mk("z@example.com"), NOW), { allowed: false, reason: "suppression_state_unavailable" });
assert.equal((await restarted.mayEmail(mk("z@example.com", "transactional"), NOW)).allowed, true);
process.env.STATE_DIR = saved;

const lines = (await readFile(join(dir, "email-optout-events.ndjson"), "utf8")).split("\n").filter(Boolean);
console.log(`ok — ${lines.length} log lines in ${dir}`);
